<?php require_once __DIR__.'/core.php'; hrRequireCsrf(); $companyId=hrCompanyId($hrDb); $month=$_GET['month']??date('Y-m'); if($_SERVER['REQUEST_METHOD']==='POST'){$month=$_POST['month'];$st=$hrDb->prepare('INSERT INTO hr_payroll_runs(company_id,payroll_month) VALUES (?,?) ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id)');$st->bind_param('is',$companyId,$month);$st->execute();$runId=$hrDb->insert_id;$st->close();$hrDb->query("DELETE FROM hr_payslips WHERE payroll_run_id=$runId");$employees=$hrDb->query("SELECT * FROM hr_employees WHERE company_id=$companyId AND status='Active'");$ins=$hrDb->prepare('INSERT INTO hr_payslips(payroll_run_id,employee_id,paid_days,basic,hra,allowance,gross,pf,esi,professional_tax,total_deductions,net_pay) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)');$workDays=(float)hrCompany($hrDb)['payroll_day'];while($e=$employees->fetch_assoc()){$abs=(int)($hrDb->query("SELECT COUNT(*) n FROM hr_attendance WHERE employee_id=".(int)$e['id']." AND DATE_FORMAT(attendance_date,'%Y-%m')='".hrEsc($hrDb,$month)."' AND status='Absent'")->fetch_assoc()['n']??0);$paid=max(0,$workDays-$abs);$ratio=$workDays?($paid/$workDays):1;$basic=(float)$e['basic_salary']*$ratio;$hra=(float)$e['hra']*$ratio;$allow=(float)$e['allowance']*$ratio;$gross=$basic+$hra+$allow;$pf=$basic*(float)$e['pf_rate']/100;$esi=$gross*(float)$e['esi_rate']/100;$tax=(float)$e['professional_tax'];$ded=$pf+$esi+$tax;$net=$gross-$ded;$employeeId=(int)$e['id'];$ins->bind_param('iidddddddddd',$runId,$employeeId,$paid,$basic,$hra,$allow,$gross,$pf,$esi,$tax,$ded,$net);$ins->execute();}$ins->close();hrFlash("Payroll calculated for $month.");header('Location: payroll.php?month='.$month);exit;} $st=$hrDb->prepare('SELECT r.*,COUNT(p.id) slips,COALESCE(SUM(p.net_pay),0) net FROM hr_payroll_runs r LEFT JOIN hr_payslips p ON p.payroll_run_id=r.id WHERE r.company_id=? AND r.payroll_month=? GROUP BY r.id');$st->bind_param('is',$companyId,$month);$st->execute();$run=$st->get_result()->fetch_assoc();$st->close();$slips=[];if($run){$r=$hrDb->query("SELECT p.*,e.employee_code,e.first_name,e.last_name,e.designation FROM hr_payslips p JOIN hr_employees e ON e.id=p.employee_id WHERE p.payroll_run_id=".(int)$run['id']." ORDER BY e.first_name");$slips=$r->fetch_all(MYSQLI_ASSOC);}hrPageStart('Payroll'); ?>
<div class="page-head"><div><h2>Salary & payroll</h2><p>Automated monthly salary calculation using each employee's configured components.</p></div></div><div class="form-card"><form method="post" class="toolbar"><input type="hidden" name="csrf" value="<?=hrCsrf()?>"><label>Payroll month<input type="month" name="month" value="<?=htmlspecialchars($month)?>"></label><button class="button">Calculate payroll</button><a class="button secondary" href="payroll.php?month=<?=date('Y-m')?>">Current month</a></form><div class="notice">Calculation applies company working days, deducts recorded <b>Absent</b> dates, then calculates PF, ESI and professional tax from each employee's salary setup. Verify statutory rates with your accountant before finalisation.</div></div><?php if($run): ?><div class="payroll-totals"><div><span>Employees paid</span><b><?=$run['slips']?></b></div><div><span>Total net payroll</span><b><?=hrMoney((float)$run['net'])?></b></div><div><span>Run status</span><b><span class="badge draft"><?=htmlspecialchars($run['status'])?></span></b></div></div><div class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>EMPLOYEE</th><th>PAID DAYS</th><th>GROSS</th><th>DEDUCTIONS</th><th>NET PAY</th><th></th></tr></thead><tbody><?php foreach($slips as $s):?><tr><td><b><?=htmlspecialchars($s['first_name'].' '.$s['last_name'])?></b><br><small><?=htmlspecialchars($s['employee_code'])?></small></td><td><?=$s['paid_days']?></td><td><?=hrMoney((float)$s['gross'])?></td><td><?=hrMoney((float)$s['total_deductions'])?></td><td><b><?=hrMoney((float)$s['net_pay'])?></b></td><td><a href="payslip.php?id=<?=$s['id']?>" class="button secondary">Payslip</a></td></tr><?php endforeach?></tbody></table></div></div><?php endif;hrPageEnd(); ?>
